export const teamTheme = id => TEAM_THEMES[id] || TEAM_THEMES.LAD;
export const TEAM_BALLPARKS={KC:'./assets/kauffman-painted.png',LAD:'./assets/dodger-stadium-painted.png'};
export const teamBallpark=id=>TEAM_BALLPARKS[id]||'';
export function applyTeamTheme(id){const t=teamTheme(id),s=document.documentElement.style,ballpark=teamBallpark(id);s.setProperty("--green",t.primary);s.setProperty("--green-dark",t.primary);s.setProperty("--team-accent",t.accent);if(ballpark)s.setProperty("--ballpark-image",`url('${ballpark}')`);else s.removeProperty("--ballpark-image");}
export function teamLogo(id,cls=""){return `<img class="team-logo ${cls}" src="${teamTheme(id).logo}" alt="${id} cap logo" width="80" height="80">`;}
export function teamHat(id,cls=""){return `<span class="team-cap ${cls}" aria-hidden="true"><span class="team-cap-crown">${teamLogo(id,'team-cap-logo')}</span><span class="team-cap-brim"></span></span>`;}
